def tr_upper(text: str) -> str:
    """ Verilen metni Türkçe büyük harf kurallarıyla büyük harfe çevir:
    'i' harfi 'İ', 'ı' harfi 'I' olur. Diğer karakterler olağan büyük harf
    dönüşümüne uyar.
    >>> tr_upper('istanbul')
    'İSTANBUL'
    >>> tr_upper('ılık')
    'ILIK'
    """
    result = []
    for char in text:
        if char == 'i':
            result.append('İ')
        elif char == 'ı':
            result.append('I')
        else:
            result.append(char.upper())
    return ''.join(result)
